using System.Buffers.Binary;
using System.Security.Cryptography;
using CsoKit.Application;
using CsoKit.Core.Formats.Containers;
using CsoKit.Core.Formats.Cso;
using CsoKit.Tests.Fixtures;

namespace CsoKit.Tests.Formats.Containers;

public sealed class ZsoDecompressionTests
{
    private const string Sha24Blocks = "1d3fae4a046574d124a0c1e2cf5c7992a24137479b75fe3c1c87677ba387f286";
    private const string Sha16kTail = "a71de97f4962ce40a77a8d8e299624a0871b19a463f4920bd4ab7f6c961c134f";

    // Generated by Fixtures/Zso/make_zso_fixtures.py with the reference LZ4 library,
    // reproducing the block layouts written by ziso.py and maxcso.
    public static TheoryData<string, long, string> WriterFixtures => new()
    {
        { "ziso-xpad-align2.zso", 24 * 2048, Sha24Blocks },
        { "maxcso-align2.zso", 24 * 2048, Sha24Blocks },
        { "maxcso-16k-tail.zso", (2 * 16384) + (3 * 2048), Sha16kTail },
    };

    [Theory]
    [MemberData(nameof(WriterFixtures))]
    public void ZsoReader_DecodesWriterLayouts(string fixture, long expectedSize, string expectedSha256)
    {
        using ZsoContainerReader reader = new(FixturePath(fixture));
        using MemoryStream iso = new();

        ulong written = ContainerIsoDecoder.Decode(reader, iso, CancellationToken.None);

        Assert.Equal((ulong)expectedSize, written);
        Assert.Equal(expectedSha256, Convert.ToHexStringLower(SHA256.HashData(iso.ToArray())));
    }

    [Theory]
    [MemberData(nameof(WriterFixtures))]
    public void Decompress_ZsoWriterLayouts_ProduceOriginalIso(string fixture, long expectedSize, string expectedSha256)
    {
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");
        List<CsoDecompressProgress> progress = [];

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(
                FixturePath(fixture),
                output,
                ForceOverwrite: false,
                Progress: new SynchronousProgress<CsoDecompressProgress>(progress.Add)));

            Assert.True(result.Success, $"{result.ErrorCode}: {result.ErrorMessage}");
            Assert.Equal((ulong)expectedSize, result.BytesWritten);
            Assert.Equal(expectedSha256, Sha256Of(output));
            Assert.Equal([Path.GetFileName(output)], Directory.GetFiles(directory).Select(Path.GetFileName));
            Assert.Equal(0, progress[0].CompletedBlocks);
            Assert.Equal(100, progress[^1].Percent);
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public void Decompress_HandEncodedZso_RoundTripsLogicalBytes()
    {
        byte[] logical = ContainerFixtures.DeterministicBytes(5 * 2048);
        string input = ContainerFixtures.CreateZso(logical);
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(input, output, false));

            Assert.True(result.Success, $"{result.ErrorCode}: {result.ErrorMessage}");
            Assert.Equal(logical, File.ReadAllBytes(output));
        }
        finally
        {
            File.Delete(input);
            Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public void OperationService_DecompressZso_ReportsZsoInputFormat()
    {
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");

        try
        {
            CsoOperationResult result = CsoOperationService.Decompress(
                FixturePath("maxcso-16k-tail.zso"),
                output,
                forceOverwrite: false,
                progress: null);

            Assert.True(result.Success, result.Details);
            CsoDecompressOperationData data = Assert.IsType<CsoDecompressOperationData>(result.Data);
            Assert.Equal("Zso", data.InputFormat);
            Assert.Equal((ulong)((2 * 16384) + (3 * 2048)), data.BytesWritten);
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Theory]
    [InlineData("maxcso-16k-tail.zso", 1)] // index_shift 0: no byte may follow the sentinel
    [InlineData("maxcso-align2.zso", 4)] // index_shift 2: a full alignment unit is never padding
    [InlineData("ziso-xpad-align2.zso", 4)]
    public void Decompress_ZsoWithDataAfterLastBlock_FailsWithoutOutput(string fixture, int extraBytes)
    {
        string directory = CreateTempDirectory();
        string input = Path.Combine(directory, "input.zso");
        string output = Path.Combine(directory, "game.iso");
        File.WriteAllBytes(input, [.. File.ReadAllBytes(FixturePath(fixture)), .. Enumerable.Repeat((byte)0xA5, extraBytes)]);

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(input, output, false));

            Assert.False(result.Success);
            Assert.Equal("InvalidCompressedData", result.ErrorCode);
            Assert.Equal(["input.zso"], Directory.GetFiles(directory).Select(Path.GetFileName));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public void Decompress_ZsoWithCorruptLz4Block_FailsAndRemovesTempOutput()
    {
        string directory = CreateTempDirectory();
        string input = Path.Combine(directory, "input.zso");
        string output = Path.Combine(directory, "game.iso");
        byte[] zso = File.ReadAllBytes(FixturePath("maxcso-16k-tail.zso"));
        uint firstEntry = BinaryPrimitives.ReadUInt32LittleEndian(zso.AsSpan(24));
        Assert.Equal(0u, firstEntry & 0x80000000u);
        zso[firstEntry & 0x7FFFFFFFu] = 0xFF; // token claims more literals than the block holds
        File.WriteAllBytes(input, zso);

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(input, output, false));

            Assert.False(result.Success);
            Assert.Equal("CorruptCompressedBlock", result.ErrorCode);
            Assert.Equal(["input.zso"], Directory.GetFiles(directory).Select(Path.GetFileName));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public void Decompress_ZsoCanceled_LeavesNoOutput()
    {
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");
        using CancellationTokenSource cancellation = new();

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(
                FixturePath("maxcso-align2.zso"),
                output,
                ForceOverwrite: false,
                Progress: new SynchronousProgress<CsoDecompressProgress>(p =>
                {
                    if (p.CompletedBlocks == 0)
                    {
                        cancellation.Cancel();
                    }
                }),
                CancellationToken: cancellation.Token));

            Assert.False(result.Success);
            Assert.Equal("OperationCanceled", result.ErrorCode);
            Assert.Empty(Directory.GetFiles(directory));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Theory]
    [InlineData("CISO")]
    [InlineData("ZISO")]
    public void OperationService_HeaderWithMaximumSize_FailsInsteadOfCrashing(string magic)
    {
        string directory = CreateTempDirectory();
        string input = Path.Combine(directory, "input.bin");
        byte[] header = new byte[24];
        System.Text.Encoding.ASCII.GetBytes(magic).CopyTo(header, 0);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(4), 24);
        BinaryPrimitives.WriteUInt64LittleEndian(header.AsSpan(8), ulong.MaxValue);
        BinaryPrimitives.WriteUInt32LittleEndian(header.AsSpan(16), 2048);
        header[20] = 1;
        File.WriteAllBytes(input, header);

        try
        {
            CsoOperationResult detect = CsoOperationService.Detect(input);
            CsoOperationResult decompress = CsoOperationService.Decompress(
                input,
                Path.Combine(directory, "game.iso"),
                forceOverwrite: false,
                progress: null);

            Assert.True(detect.Success);
            Assert.False(decompress.Success);
            Assert.Equal(["input.bin"], Directory.GetFiles(directory).Select(Path.GetFileName));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Theory]
    [InlineData(0, 0, true)]
    [InlineData(3, 0, false)]
    [InlineData(3, 3, true)]
    [InlineData(4, 3, false)]
    public void Lz4Decoder_AllowsNonZeroTrailerOnlyWithinPaddingLimit(int trailerLength, int maxTrailingBytes, bool expected)
    {
        byte[] block = [0x80, .. "ABCDEFGH"u8, .. Enumerable.Repeat((byte)'X', trailerLength)];
        byte[] output = new byte[8];

        bool decoded = Lz4BlockDecoder.TryDecode(block, output, out int written, maxTrailingBytes);

        Assert.Equal(expected, decoded);
        Assert.Equal(expected ? 8 : 0, written);
    }

    [Fact]
    public void Lz4Decoder_AllowsZeroTrailerOfAnyLength()
    {
        byte[] block = [0x80, .. "ABCDEFGH"u8, .. new byte[64]];

        Assert.True(Lz4BlockDecoder.TryDecode(block, new byte[8], out int written));
        Assert.Equal(8, written);
    }

    private static string FixturePath(string name)
    {
        return Path.Combine(AppContext.BaseDirectory, "Fixtures", "Zso", name);
    }

    private static string Sha256Of(string path)
    {
        using FileStream stream = File.OpenRead(path);
        return Convert.ToHexStringLower(SHA256.HashData(stream));
    }

    private static string CreateTempDirectory()
    {
        string directory = Path.Combine(Path.GetTempPath(), $"csokit-zso-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        return directory;
    }

    private sealed class SynchronousProgress<T>(Action<T> report) : IProgress<T>
    {
        public void Report(T value) => report(value);
    }
}
